/* Start here entry for gravity-near-earth (demos/lib/starthere/gravity-near-earth.js). Generated by tools/activities.py from curriculum/start-here.json:
   edit the data, not this file. demos/lib/starthere.js loads it. */
window.VDStartHere && VDStartHere({"q":"Is there gravity up where the space station flies?","q_es":"¿Hay gravedad allá arriba, donde vuela la estación espacial?","setup":"","do":"A 1.000 kg mass sits on a spring scale at sea level on the equator, where <b>Gravity alone GM/r²</b> reads 9.8203 m/s². Decide what fraction of that is left 400 km up, then press <b>Space station, about 400 km</b> and read <b>Fraction of surface value</b>.","do_es":"Una masa de 1.000 kg está en una báscula de resorte al nivel del mar en el ecuador, donde <b>Gravedad sola GM/r²</b> marca 9.8203 m/s². Decide qué fracción queda 400 km más arriba, luego presiona <b>Estación espacial, unos 400 km</b> y lee la <b>Fracción del valor en la superficie</b>.","see":"88.53 %: gravity there is still 8.6943 m/s². The station is 6,771 km from Earth's center, only 6 % farther than the ground at 6,371 km, so g = GM/r² drops by (6,371/6,771)² = 0.885. Astronauts float because they and the station fall together, which is why the readout says the same scale in orbit reads 0.","see_es":"88.53 %: ahí la gravedad todavía es 8.6943 m/s². La estación está a 6,771 km del centro de la Tierra, solo 6 % más lejos que el suelo a 6,371 km, así que g = GM/r² baja por un factor (6,371/6,771)² = 0.885. Los astronautas flotan porque ellos y la estación caen juntos; por eso la lectura dice que la misma báscula en órbita marca 0.","explore":[{"setup":"","do":"Press <b>Geostationary, r = 42,164 km</b>. Before you read anything, decide what the 1.000 kg on a spring scale would read on a tower that tall, turning with Earth. Then read the scale line and <b>Orbit period</b>.","do_es":"Presiona <b>Geoestacionaria, r = 42,164 km</b>. Antes de leer nada, decide qué marcaría el kilogramo en la báscula de resorte sobre una torre así de alta, girando con la Tierra. Luego lee la línea de la báscula y el <b>Periodo de la órbita</b>.","see":"0.000 N. Gravity there is only 0.2242 m/s², and the <b>Centrifugal term ω²r cos(lat)</b> is also 0.2242 m/s²: all of gravity goes into carrying the mass round the circle once a day. The <b>Orbit period</b>, 1436.1 min, is one sidereal day, so a satellite there stays over the same spot on the equator.","see_es":"0.000 N. Ahí la gravedad es solo 0.2242 m/s², y el <b>Término centrífugo ω²r cos(lat)</b> también es 0.2242 m/s²: toda la gravedad se usa en llevar la masa por su círculo una vez al día. El <b>Periodo de la órbita</b>, 1436.1 min, es un día sideral, así que un satélite ahí se queda sobre el mismo punto del ecuador."},{"setup":"","do":"At sea level, drag <b>Latitude</b> from 0° to 90° and watch <b>Effective g (what a scale feels)</b>. Predict the change from the spin alone, ω²R = 0.0339 m/s², then compare with <b>Real Earth at sea level (WGS 84)</b> at both ends.","do_es":"Al nivel del mar, arrastra la <b>Latitud</b> de 0° a 90° y observa la <b>g efectiva (lo que siente una báscula)</b>. Predice el cambio debido solo al giro, ω²R = 0.0339 m/s², y luego compara con <b>Tierra real al nivel del mar (WGS 84)</b> en los dos extremos.","see":"The model goes from 9.7864 to 9.8203 m/s², exactly the 0.0339 m/s² the spin takes off at the equator. The real Earth goes from 9.7803 to 9.8322 m/s², a difference of 0.0519 m/s²: Earth is also flattened, so the poles are closer to its center, which this sphere leaves out.","see_es":"El modelo va de 9.7864 a 9.8203 m/s², justo los 0.0339 m/s² que el giro quita en el ecuador. La Tierra real va de 9.7803 a 9.8322 m/s², una diferencia de 0.0519 m/s²: además la Tierra está achatada, así que los polos están más cerca de su centro, algo que esta esfera deja fuera."},{"setup":"","do":"Press <b>Moon</b>. The Moon has 1/81.3 of Earth's GM and a radius 3.67 times smaller; predict <b>Gravity alone GM/r²</b> at its surface from Earth's 9.8203 m/s², then read it. Then press <b>Mars</b> and read the 1.000 kg on a spring scale line.","do_es":"Presiona <b>Luna</b>. La Luna tiene 1/81.3 del GM de la Tierra y un radio 3.67 veces menor; predice la <b>Gravedad sola GM/r²</b> en su superficie a partir de los 9.8203 m/s² de la Tierra y luego léela. Después presiona <b>Marte</b> y lee la línea del kilogramo en la báscula de resorte.","see":"1.6242 m/s², a sixth of Earth's: 81.3/3.67² = 6.04, and 9.8203/6.04 = 1.62. The smaller mass would cut g 81 times, but standing 3.67 times closer to the center wins back a factor of 13.4. On <b>Mars</b> the scale reads 3.711 N.","see_es":"1.6242 m/s², un sexto de la de la Tierra: 81.3/3.67² = 6.04, y 9.8203/6.04 = 1.62. La masa menor reduciría g 81 veces, pero estar 3.67 veces más cerca del centro recupera un factor de 13.4. En <b>Marte</b> la báscula marca 3.711 N."}]});
